import sys
import inspect


def get_module_interface(module_name):
    """Returns list of public items (classes, functions and variables) declared in the module"""
    module = sys.modules[module_name]
    return [itemname for itemname, obj in inspect.getmembers(module) if (_is_primitive(obj) or obj.__module__ == module_name) and
            not itemname.startswith('_') and not inspect.ismodule(obj)]


def _is_primitive(obj):
    return not hasattr(obj, '__module__')
